#!/usr/bin/env python3
"""Polymarket research skill script.

Usage: python3 polymarket.py [--json] [--chart] "<query or URL or slug>"
"""
from __future__ import annotations

import argparse
import json
import os
import re
import subprocess
import sys


def run(cmd: list[str]) -> tuple[str, int]:
    """Run a command and return (output, returncode)."""
    try:
        result = subprocess.run(
            cmd, capture_output=True, text=True, timeout=30
        )
        out = result.stdout.strip()
        if result.returncode != 0 and result.stderr.strip():
            out = (out + "\n" + result.stderr.strip()).strip()
        return out, result.returncode
    except subprocess.TimeoutExpired:
        return "[Timeout after 30s]", 1
    except Exception as exc:
        return f"[Error: {exc}]", 1


def extract_slug(url: str) -> str:
    """Extract the last path segment as slug from a URL."""
    return url.rstrip("/").split("/")[-1]


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Polymarket research skill — look up events, markets, and generate charts",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
  python3 polymarket.py "trump"
  python3 polymarket.py --json "https://polymarket.com/event/democratic-presidential-nominee-2028"
  python3 polymarket.py --chart "newsom"
        """
    )
    parser.add_argument("query", nargs="+", help="Query, URL, or slug to look up")
    parser.add_argument("--json", action="store_true", dest="raw_json",
                        help="Output raw JSON from CLI instead of formatted summary")
    parser.add_argument("--chart", action="store_true",
                        help="Auto-generate a price chart for the first result")
    args = parser.parse_args()
    query = " ".join(args.query).strip()

    if not query:
        parser.print_help()
        sys.exit(1)

    condition_id = None

    # Detect input type
    if "polymarket.com/event/" in query:
        slug = extract_slug(query)
        print(f"# Event: {slug}\n")
        out, rc = run(["polymarket", "-o", "json", "events", "get", slug])
        if args.raw_json:
            print(out)
        else:
            _format_event_output(out, rc)
        # Extract conditionId for chart
        try:
            data = json.loads(out)
            markets = data.get("markets", [])
            if markets:
                condition_id = markets[0].get("conditionId")
        except (json.JSONDecodeError, AttributeError):
            pass

    elif "polymarket.com/market/" in query:
        slug = extract_slug(query)
        print(f"# Market: {slug}\n")
        out, rc = run(["polymarket", "-o", "json", "markets", "get", slug])
        if args.raw_json:
            print(out)
        else:
            print(out)
        try:
            data = json.loads(out)
            condition_id = data.get("conditionId")
        except (json.JSONDecodeError, AttributeError):
            pass

    else:
        # Search or slug fallback
        print(f"# Polymarket search: {query}\n")
        out, rc = run(["polymarket", "-o", "json", "markets", "search", query, "--limit", "10"])

        if rc != 0 or not out.strip():
            print(f"Search failed or empty: {out}")
            print(f"\n# Trying as event slug: {query}\n")
            out2, rc2 = run(["polymarket", "-o", "json", "events", "get", query])
            if rc2 == 0:
                if args.raw_json:
                    print(out2)
                else:
                    _format_event_output(out2, rc2)
                try:
                    data = json.loads(out2)
                    markets = data.get("markets", [])
                    if markets:
                        condition_id = markets[0].get("conditionId")
                except (json.JSONDecodeError, AttributeError):
                    pass
            else:
                print(f"\n# Trying as market slug: {query}\n")
                out3, rc3 = run(["polymarket", "-o", "json", "markets", "get", query])
                if args.raw_json:
                    print(out3)
                else:
                    print(out3)
                try:
                    data = json.loads(out3)
                    condition_id = data.get("conditionId")
                except (json.JSONDecodeError, AttributeError):
                    pass
        else:
            if args.raw_json:
                print(out)
            else:
                _format_search_output(out)
            # Get conditionId from first result
            try:
                data = json.loads(out)
                markets = data if isinstance(data, list) else data.get("markets", [data])
                if markets:
                    condition_id = markets[0].get("conditionId")
            except (json.JSONDecodeError, AttributeError):
                pass

    # Auto-chain into chart if requested
    if args.chart and condition_id:
        print(f"\n# Generating chart for conditionId: {condition_id}\n")
        chart_script = os.path.join(os.path.dirname(os.path.abspath(__file__)), "chart.py")
        os.system(f'python3 "{chart_script}" --condition-id {condition_id}')
    elif args.chart and not condition_id:
        print("\nCould not extract conditionId for chart generation.", file=sys.stderr)


def _format_event_output(out: str, rc: int) -> None:
    """Format event JSON output as readable summary."""
    try:
        data = json.loads(out)
        title = data.get("title", "Unknown Event")
        print(f"**{title}**\n")
        markets = data.get("markets", [])
        if markets:
            print(f"Found {len(markets)} outcomes:\n")
            for m in markets:
                _print_market_summary(m)
        else:
            print(out)
    except json.JSONDecodeError:
        print(out)


def _format_search_output(out: str) -> None:
    """Format search JSON output as readable summary."""
    try:
        data = json.loads(out)
        markets = data if isinstance(data, list) else data.get("markets", [data])
        print(f"Found {len(markets)} markets:\n")
        for m in markets:
            _print_market_summary(m)
    except json.JSONDecodeError:
        print(out)


def _print_market_summary(m: dict) -> None:
    """Print a single market as a formatted summary line."""
    question = m.get("question", m.get("title", "?"))
    prices_raw = m.get("outcomePrices", "[]")
    try:
        prices = json.loads(prices_raw) if isinstance(prices_raw, str) else prices_raw
    except Exception:
        prices = []
    volume = m.get("volume", m.get("volumeNum", "?"))
    liquidity = m.get("liquidity", "?")
    active = m.get("active", True)
    status = "Active" if active else "Closed"
    slug = m.get("slug", "")
    cond_id = m.get("conditionId", "")

    print(f"- {question}")
    if prices:
        try:
            yes_price = float(prices[0]) * 100
            no_price = float(prices[1]) * 100 if len(prices) > 1 else 100 - yes_price
            print(f"  YES: {yes_price:.1f}\u00a2  NO: {no_price:.1f}\u00a2")
        except Exception:
            print(f"  Prices: {prices}")
    print(f"  Volume: {volume}  Liquidity: {liquidity}  Status: {status}")
    if slug:
        print(f"  Slug: {slug}")
    if cond_id:
        print(f"  ConditionID: {cond_id}")
    print()


if __name__ == "__main__":
    main()

